// Search across the command reference: commands, sections and options of every page.
// Data: search-index.js (window.REF_INDEX, generated by ref_index.py); load it first.
// Mounts into every <div data-ref-search="PREFIX">, where PREFIX is the path from that page to docs/commands/
// ("" on the reference pages, "commands/" in the guide). "/" focuses the box from anywhere on the page.
(function () {
  var INDEX = window.REF_INDEX || [];
  var MAX = 8;
  var KIND = { cmd: 'Command', opt: 'Option', sec: 'Section', area: 'Page' };
  var BONUS = { cmd: 6, area: 5, opt: 4, sec: 2 };

  var css = document.createElement('style');
  css.textContent =
    '.rs{position:relative;margin:0 0 14px}' +
    '.rs input{width:100%;box-sizing:border-box;padding:8px 12px;border:1px solid var(--line);border-radius:8px;' +
      'background:var(--surface);color:var(--text);font:inherit;font-size:14px}' +
    '.rs input:focus{outline:none;border-color:var(--accent)}' +
    '.rs ol{list-style:none;margin:6px 0 0;padding:4px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}' +
    '.rs li{margin:0;padding:0}' +
    '.rs li::before{content:none}' +
    '.rs ol li a{display:block;padding:6px 8px;border:0;border-radius:6px;color:var(--text);text-decoration:none;line-height:1.35;font-size:14px}' +
    '.rs ol li a.on,.rs ol li a:hover{background:var(--accent-soft);color:var(--text)}' +
    '.rs .t{font-weight:600}.rs .t.code{font-family:var(--mono);font-size:13px}' +
    '.rs .m{font-size:12px;color:var(--muted);margin-top:2px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}' +
    '.rs .k{font-size:11px;color:var(--muted);margin-left:6px}' +
    '.rs .none{padding:6px 8px;font-size:13px;color:var(--muted)}';
  document.head.appendChild(css);

  function esc(s) { return s.replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

  // Every word must appear somewhere; title hits count most, exact and prefix title hits more still.
  function search(q) {
    var words = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    var bare = q.toLowerCase().trim().replace(/^-+/, '');
    var hits = [];
    INDEX.forEach(function (e, i) {
      var t = e.t.toLowerCase(), tb = t.replace(/^-+/, ''), rest = (e.a + ' ' + e.d).toLowerCase();
      var score = 0;
      for (var w = 0; w < words.length; w++) {
        var word = words[w];
        if (t.indexOf(word) >= 0) score += 10;
        else if (rest.indexOf(word) >= 0) score += 2;
        else return;
      }
      if (tb === bare || tb.split(' ')[0] === bare) score += 30;
      else if (tb.indexOf(bare) === 0) score += 15;
      hits.push({ e: e, s: score + BONUS[e.k], i: i });
    });
    hits.sort(function (a, b) { return b.s - a.s || a.i - b.i; });
    return hits.slice(0, MAX).map(function (h) { return h.e; });
  }

  function mount(box) {
    var prefix = box.getAttribute('data-ref-search') || '';
    box.classList.add('rs');
    box.innerHTML = '<input type="search" placeholder="Search commands and options…  ( / )" ' +
      'aria-label="Search commands and options" autocomplete="off" spellcheck="false"><ol hidden></ol>';
    var input = box.querySelector('input'), list = box.querySelector('ol'), active = 0;

    function show() {
      var q = input.value.trim(), found = search(q);
      active = 0;
      if (!q) { list.hidden = true; list.innerHTML = ''; return; }
      list.innerHTML = found.length ? found.map(function (e, i) {
        var where = [KIND[e.k], e.a].filter(Boolean).join(' · ');
        return '<li><a href="' + esc(prefix + e.u) + '"' + (i === 0 ? ' class="on"' : '') + '>' +
          '<span class="t' + (e.k === 'cmd' || e.k === 'opt' ? ' code' : '') + '">' + esc(e.t) + '</span><span class="k">' + esc(where) + '</span>' +
          (e.d ? '<span class="m">' + esc(e.d) + '</span>' : '') + '</a></li>';
      }).join('') : '<li class="none">Nothing found. <code>uv run dj-track-analyzer &lt;command&gt; --help</code> lists a command\'s options.</li>';
      list.hidden = false;
    }
    function move(d) {
      var links = list.querySelectorAll('a');
      if (!links.length) return;
      links[active].classList.remove('on');
      active = (active + d + links.length) % links.length;
      links[active].classList.add('on');
      links[active].scrollIntoView({ block: 'nearest' });
    }
    input.addEventListener('input', show);
    input.addEventListener('keydown', function (ev) {
      if (ev.key === 'ArrowDown') { ev.preventDefault(); move(1); }
      else if (ev.key === 'ArrowUp') { ev.preventDefault(); move(-1); }
      else if (ev.key === 'Enter') { var a = list.querySelectorAll('a')[active]; if (a) { ev.preventDefault(); a.click(); } }
      else if (ev.key === 'Escape') { input.value = ''; show(); }
    });
  }

  var boxes = document.querySelectorAll('[data-ref-search]');
  Array.prototype.forEach.call(boxes, mount);
  document.addEventListener('keydown', function (ev) {
    var tag = (ev.target.tagName || '').toLowerCase();
    if (ev.key !== '/' || ev.metaKey || ev.ctrlKey || tag === 'input' || tag === 'textarea' || ev.target.isContentEditable) return;
    var first = document.querySelector('.rs input');
    if (first) { ev.preventDefault(); first.focus(); }
  });
})();
